#include <array>
#include <iostream>
#include <stdexcept>
template<class T, std::size_t N>
class FixedBuffer {
public:
    T& at(std::size_t i) { return data_.at(i); }
    constexpr std::size_t size() const { return N; }
    auto begin() { return data_.begin(); }
    auto end() { return data_.end(); }
private: std::array<T, N> data_{};
};
int main() { FixedBuffer<int, 3> values; values.at(0)=4; values.at(1)=5; values.at(2)=6; int total=0; for (int n: values) total+=n; std::cout << total << '\n'; }
